// Tests for published rules whose upstream tests need a database or mock other modules, written for this
// repository. Upstream tests that run standalone are in test/upstream/ (generated by scripts/sync.ts).
import { describe, expect, it } from "bun:test";
import {
  buildTradePlan, decideUsdcResidual, isTokenizedEquityWashEligible, buildWashEligibleFn, isWithinWashWindow,
  washWindowClearsAtSecs, reconcileLotsToChainQty, reviewInKindContributionFacts, splitSolSale, isSolDustPosition,
  solTransferAtoms, SOL_NATIVE_BUFFER_LAMPORTS, truncTo, DEFAULT_CONFIG, type InKindContributionFacts, type PlannerInput,
} from "../src/rules";

const DAY = 86_400;
const T0 = Date.UTC(2026, 0, 15) / 1000;

describe("harvest eligibility headline rules (planner)", () => {
  const input = (price: number, basis: number, qty: number): PlannerInput => ({
    members: [{ assetId: "eth", targetWeightBps: 10_000, eligible: true }],
    assets: { eth: { assetId: "eth", priceUsd: price, lots: [{ lotId: "l1", qty, basisPerUnitUsd: basis, acquiredAt: T0 - 10 * DAY }] } },
    cashUsd: 0, washSalePolicy: "non-security", taxRateStBps: 3700, taxRateLtBps: 2000, asOf: T0, config: DEFAULT_CONFIG,
  });
  it("harvests a lot at least 1% below basis, and rebuys the same asset (crypto)", () => {
    const plan = buildTradePlan(input(98, 100, 10)); // 2% down, $20 loss
    expect(plan.legs.map((l) => `${l.side}:${l.reason}`)).toEqual(["sell:harvest", "buy:harvest_rebuy"]);
  });
  it("does not harvest a lot less than 1% below basis", () => {
    expect(buildTradePlan(input(99.5, 100, 1000)).legs).toEqual([]);
  });
  it("does not harvest a crypto sale realizing less than $1 of loss", () => {
    const plan = buildTradePlan(input(98, 100, 0.4)); // $0.80 loss
    expect(plan.legs).toEqual([]);
    expect(plan.notes.some((n) => n.includes("below $1 minimum loss"))).toBe(true);
  });
  it("never sells a gain lot", () => {
    expect(buildTradePlan(input(150, 100, 10)).legs).toEqual([]);
  });
});

describe("wash window (§1091, 30 days either side, by UTC day)", () => {
  it("covers 30 days either side and clears on day 31", () => {
    expect(isWithinWashWindow(T0 + 30 * DAY, T0)).toBe(true);
    expect(isWithinWashWindow(T0 - 30 * DAY, T0)).toBe(true);
    expect(isWithinWashWindow(T0 + 31 * DAY, T0)).toBe(false);
    expect(washWindowClearsAtSecs(T0 + 3600)).toBe(T0 + 31 * DAY);
  });
  it("fails closed (inside the window) on non-finite times", () => {
    expect(isWithinWashWindow(Number.NaN, T0)).toBe(true);
  });
  it("only stock or securities wash: tokenized equities always, catalogue-listed ids additionally", () => {
    expect(isTokenizedEquityWashEligible("apple-xstock")).toBe(true);
    expect(isTokenizedEquityWashEligible("ethereum")).toBe(false);
    const f = buildWashEligibleFn(new Set(["some-equity"]));
    expect(f("some-equity")).toBe(true);
    expect(f("apple-xstock")).toBe(true);
    expect(f("ethereum")).toBe(false);
    expect(f(null)).toBe(false);
  });
});

describe("exit rules", () => {
  it("reconcileLotsToChainQty trims keeping the HIGHEST-basis lots", () => {
    const lots = [
      { lotId: "lo", qty: 1, basisPerUnitUsd: 10, acquiredAt: 1 },
      { lotId: "hi", qty: 1, basisPerUnitUsd: 30, acquiredAt: 2 },
    ];
    expect(reconcileLotsToChainQty(lots, 1.5, 100).map((l) => [l.lotId, l.qty])).toEqual([["hi", 1], ["lo", 0.5]]);
  });
  it("reconcileLotsToChainQty adds a zero-basis remainder for a chain surplus", () => {
    const out = reconcileLotsToChainQty([{ lotId: "a", qty: 1, basisPerUnitUsd: 10, acquiredAt: 1 }], 1.25, 100);
    expect(out.at(-1)).toEqual({ lotId: "chain-remainder", qty: 0.25, basisPerUnitUsd: 0, acquiredAt: 100 });
  });
  it("decideUsdcResidual never re-sends after a confirmed sweep, and never closes with cash stranded", () => {
    expect(decideUsdcResidual({ residualUsdcQty: 0, dustThreshold: 1e-6, hasConfirmedPriorSweep: false, hasDestination: false })).toBe("close");
    expect(decideUsdcResidual({ residualUsdcQty: 5, dustThreshold: 1e-6, hasConfirmedPriorSweep: true, hasDestination: true })).toBe("residual_after_sweep");
    expect(decideUsdcResidual({ residualUsdcQty: 5, dustThreshold: 1e-6, hasConfirmedPriorSweep: false, hasDestination: true })).toBe("sweep");
    expect(decideUsdcResidual({ residualUsdcQty: 5, dustThreshold: 1e-6, hasConfirmedPriorSweep: false, hasDestination: false })).toBe("no_destination");
  });
});

describe("SOL position rules", () => {
  const folded = { wsolAtoms: 0n, nativeFolded: true };
  it("never plans the native fee/rent buffer", () => {
    expect(solTransferAtoms(folded, SOL_NATIVE_BUFFER_LAMPORTS)).toBe(0n);
    expect(isSolDustPosition(folded, SOL_NATIVE_BUFFER_LAMPORTS + 1_000_000n)).toBe(true);
    expect(splitSolSale(folded, SOL_NATIVE_BUFFER_LAMPORTS + 3_000_000n)).toEqual([3_000_000n]);
  });
  it("sells held wSOL first, then native above the buffer", () => {
    expect(splitSolSale({ wsolAtoms: 4_000_000n, nativeFolded: true }, 4_000_000n + SOL_NATIVE_BUFFER_LAMPORTS + 2_500_000n)).toEqual([4_000_000n, 2_500_000n]);
  });
});

describe("truncTo (dp = 0 only)", () => {
  it("truncates toward zero after removing float noise", () => {
    expect(truncTo(0.29 * 100)).toBe(29); // 28.999999999999996 → 29
    expect(truncTo(-1.7)).toBe(-1);
    expect(() => truncTo(1.234, 2)).toThrow();
  });
});

describe("in-kind contribution lot election", () => {
  const lots = [
    { displayLotId: "old-cheap", qty: 1, basisPerUnitUsd: 50, acquiredAt: 100, location: "spot", source: "trade" },
    { displayLotId: "new-dear", qty: 1, basisPerUnitUsd: 90, acquiredAt: 200, location: "spot", source: "trade" },
    { displayLotId: "lent", qty: 5, basisPerUnitUsd: 70, acquiredAt: 150, location: "lending", source: "trade" },
  ];
  const facts = (over: Partial<InKindContributionFacts> = {}): InKindContributionFacts => ({
    amountAtoms: "1500000000", mint: "MintPlaceholder1111111111111111111111111111", decimals: 9,
    strategy: { kind: "crypto-single-asset-tlh", status: "live", minDepositUsd: 100 },
    members: [{ assetId: "token", eligible: true }],
    sourceWallet: { isUserHostedWallet: true, managedByStrategyEnrollmentId: null },
    asset: { symbol: "TKN", mint: "MintPlaceholder1111111111111111111111111111", decimals: 9 },
    priceUsd: 80, method: "HIFO", openLots: lots, availableQtyById: new Map([["old-cheap", 1], ["new-dear", 1], ["lent", 5]]),
    ...over,
  });
  it("HIFO: highest-basis spot lots move first; lent lots never move", () => {
    const r = reviewInKindContributionFacts(facts());
    expect(r.ok).toBe(true);
    if (r.ok) expect(r.lots.map((l) => [l.lotId, l.qty])).toEqual([["new-dear", 1], ["old-cheap", 0.5]]);
  });
  it("FIFO: oldest first", () => {
    const r = reviewInKindContributionFacts(facts({ method: "FIFO" }));
    if (!r.ok) throw new Error(r.code);
    expect(r.lots[0]!.lotId).toBe("old-cheap");
  });
  it("USDC is never contributed in kind", () => {
    const r = reviewInKindContributionFacts(facts({ mint: "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v" }));
    expect(r.ok ? "ok" : r.code).toBe("strategy_not_eligible");
  });
  it("only single-asset crypto strategies accept in-kind contributions", () => {
    const r = reviewInKindContributionFacts(facts({ strategy: { kind: "index", status: "live", minDepositUsd: 100 } }));
    expect(r.ok ? "ok" : r.code).toBe("strategy_not_eligible");
  });
  it("single-asset minimum is $5", () => {
    const r = reviewInKindContributionFacts(facts({ amountAtoms: "50000000" })); // 0.05 × $80 = $4
    expect(r.ok ? "ok" : r.code).toBe("strategy_min_deposit");
  });
  it("refuses a lot without a recorded basis instead of guessing one", () => {
    const r = reviewInKindContributionFacts(facts({ openLots: [{ ...lots[1]!, source: "unknown" }] }));
    expect(r.ok ? "ok" : r.code).toBe("basis_reconciliation_required");
  });
  it("refuses when verified lots do not cover the amount", () => {
    const r = reviewInKindContributionFacts(facts({ amountAtoms: "5000000000" }));
    expect(r.ok ? "ok" : r.code).toBe("insufficient_lots");
  });
  it("refuses a managed (position) wallet as the source", () => {
    const r = reviewInKindContributionFacts(facts({ sourceWallet: { isUserHostedWallet: true, managedByStrategyEnrollmentId: "enr_x" } }));
    expect(r.ok ? "ok" : r.code).toBe("source_not_eligible");
  });
});
